file.content:
{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7594.md",
  "title": "EIP-7594: PeerDAS - Peer Data Availability Sampling",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "consensus+networking",
  "description": "Introducing simple DAS utilizing gossip distribution and peer requests. Extends EIP-4844 blobs using 1D erasure coding, column-based sampling, and introduces a 6-blob-per-transaction limit.",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "1D Erasure Coding Extension",
      "description": "Extends EIP-4844 blobs using one-dimensional Reed-Solomon erasure coding. Each blob (row) is extended into CELLS_PER_EXT_BLOB cells, doubling the original data via erasure coding. Cells are the smallest authenticated units. The extended data forms a matrix with MAX_BLOBS_PER_BLOCK rows and NUMBER_OF_COLUMNS (128) columns.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "FIELD_ELEMENTS_PER_EXT_BLOB == 2 * FIELD_ELEMENTS_PER_BLOB: the extended blob always has exactly twice the field elements of the original blob."
        },
        {
          "id": "INV-002",
          "text": "CELLS_PER_EXT_BLOB == FIELD_ELEMENTS_PER_EXT_BLOB // FIELD_ELEMENTS_PER_CELL: the number of cells per extended blob is derived deterministically from field element counts."
        },
        {
          "id": "INV-003",
          "text": "NUMBER_OF_COLUMNS == CELLS_PER_EXT_BLOB (= 128): the number of columns in the data matrix equals the number of cells per extended blob."
        },
        {
          "id": "INV-004",
          "text": "Each cell can be independently verified against its blob's KZG commitment using its cell KZG proof."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-001",
          "text": "Input blob must satisfy len(blob) == BYTES_PER_BLOB."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-001",
          "text": "compute_cells returns exactly CELLS_PER_EXT_BLOB cells for each input blob."
        },
        {
          "id": "POST-002",
          "text": "compute_cells_and_kzg_proofs returns both CELLS_PER_EXT_BLOB cells and CELLS_PER_EXT_BLOB KZG proofs."
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "signature": "compute_cells(blob: Blob) -> Vector[Cell, CELLS_PER_EXT_BLOB]",
          "description": "Given a blob, extends it using erasure coding and returns all cells of the extended blob. Public method.",
          "classification": "public"
        },
        {
          "id": "FN-002",
          "signature": "compute_cells_and_kzg_proofs(blob: Blob) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]",
          "description": "Computes all cell proofs for an extended blob. Uses O(n^2) algorithm; FK20 O(n log n) recommended for production. Public method.",
          "classification": "public"
        },
        {
          "id": "FN-003",
          "signature": "compute_cells_and_kzg_proofs_polynomialcoeff(polynomial_coeff: PolynomialCoeff) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]",
          "description": "Helper that computes cells and proofs from a polynomial in coefficient form.",
          "classification": "internal"
        },
        {
          "id": "FN-004",
          "signature": "cell_to_coset_evals(cell: Cell) -> CosetEvals",
          "description": "Converts an untrusted Cell into a trusted CosetEvals by deserializing field elements.",
          "classification": "internal"
        },
        {
          "id": "FN-005",
          "signature": "coset_evals_to_cell(coset_evals: CosetEvals) -> Cell",
          "description": "Converts trusted CosetEvals back into an untrusted Cell by serializing field elements.",
          "classification": "internal"
        }
      ],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "Cell",
          "definition": "ByteVector[BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL]",
          "description": "The unit of blob data that can come with its own KZG proof."
        },
        {
          "id": "DS-002",
          "name": "CellIndex",
          "definition": "uint64",
          "description": "Cell index. Validation: x < CELLS_PER_EXT_BLOB."
        },
        {
          "id": "DS-003",
          "name": "PolynomialCoeff",
          "definition": "List[BLSFieldElement, FIELD_ELEMENTS_PER_EXT_BLOB]",
          "description": "A polynomial in coefficient form."
        },
        {
          "id": "DS-004",
          "name": "Coset",
          "definition": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]",
          "description": "The evaluation domain of a cell."
        },
        {
          "id": "DS-005",
          "name": "CosetEvals",
          "definition": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]",
          "description": "A cell's evaluations over its coset."
        }
      ],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "FIELD_ELEMENTS_PER_EXT_BLOB",
          "value": "2 * FIELD_ELEMENTS_PER_BLOB",
          "description": "Number of field elements in a Reed-Solomon extended blob."
        },
        {
          "id": "SV-002",
          "name": "FIELD_ELEMENTS_PER_CELL",
          "value": "uint64(64)",
          "description": "Number of field elements in a cell."
        },
        {
          "id": "SV-003",
          "name": "BYTES_PER_CELL",
          "value": "FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT",
          "description": "The number of bytes in a cell."
        },
        {
          "id": "SV-004",
          "name": "CELLS_PER_EXT_BLOB",
          "value": "FIELD_ELEMENTS_PER_EXT_BLOB // FIELD_ELEMENTS_PER_CELL",
          "description": "The number of cells in an extended blob."
        }
      ]
    },
    {
      "id": "SG-002",
      "name": "KZG Polynomial Commitment Verification",
      "description": "Defines the KZG-based cryptographic verification mechanism for cells. Implements a universal verification equation for batch-verifying that cells belong to their corresponding commitments using pairings over BLS12-381.",
      "invariants": [
        {
          "id": "INV-005",
          "text": "verify_cell_kzg_proof_batch returns True if and only if all cells are valid evaluations of their respective committed polynomials at the specified coset indices."
        },
        {
          "id": "INV-006",
          "text": "The batch verification challenge r is deterministically derived via Fiat-Shamir heuristic from all prover-provided data, ensuring non-interactivity."
        },
        {
          "id": "INV-007",
          "text": "Commitments in the batch verification must contain no duplicates: len(commitments) == len(set(commitments))."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-002",
          "text": "len(commitments_bytes) == len(cells) == len(proofs_bytes) == len(cell_indices)."
        },
        {
          "id": "PRE-003",
          "text": "Each commitment_bytes has length BYTES_PER_COMMITMENT."
        },
        {
          "id": "PRE-004",
          "text": "Each cell_index < CELLS_PER_EXT_BLOB."
        },
        {
          "id": "PRE-005",
          "text": "Each cell has length BYTES_PER_CELL."
        },
        {
          "id": "PRE-006",
          "text": "Each proof_bytes has length BYTES_PER_PROOF."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-003",
          "text": "Returns bool indicating whether all provided cells pass the pairing-based verification equation."
        }
      ],
      "functions": [
        {
          "id": "FN-006",
          "signature": "verify_cell_kzg_proof_batch(commitments_bytes: Sequence[Bytes48], cell_indices: Sequence[CellIndex], cells: Sequence[Cell], proofs_bytes: Sequence[Bytes48]) -> bool",
          "description": "Verify that a set of cells belong to their corresponding commitments. Implements the universal verification equation. Public method.",
          "classification": "public"
        },
        {
          "id": "FN-007",
          "signature": "verify_cell_kzg_proof_batch_impl(commitments: Sequence[KZGCommitment], commitment_indices: Sequence[CommitmentIndex], cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals], proofs: Sequence[KZGProof]) -> bool",
          "description": "Internal implementation of batch cell KZG proof verification using the pairing-based universal verification equation.",
          "classification": "internal"
        },
        {
          "id": "FN-008",
          "signature": "compute_verify_cell_kzg_proof_batch_challenge(commitments: Sequence[KZGCommitment], commitment_indices: Sequence[CommitmentIndex], cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals], proofs: Sequence[KZGProof]) -> BLSFieldElement",
          "description": "Computes a random challenge r via Fiat-Shamir for the universal verification equation.",
          "classification": "internal"
        },
        {
          "id": "FN-009",
          "signature": "compute_kzg_proof_multi_impl(polynomial_coeff: PolynomialCoeff, zs: Coset) -> Tuple[KZGProof, CosetEvals]",
          "description": "Computes a KZG multi-evaluation proof for a set of k points via quotient polynomial Q(X) = f(X) / Z(X).",
          "classification": "internal"
        }
      ],
      "data_structures": [
        {
          "id": "DS-006",
          "name": "CommitmentIndex",
          "definition": "uint64",
          "description": "Index of an element in the list of commitments."
        }
      ],
      "state_variables": [
        {
          "id": "SV-005",
          "name": "RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN",
          "value": "b'RCKZGCBATCH__V1_'",
          "description": "Domain separator for the Fiat-Shamir challenge computation in batch cell KZG proof verification."
        }
      ]
    },
    {
      "id": "SG-003",
      "name": "Polynomial Arithmetic Helpers",
      "description": "Provides FFT-based and coefficient-form polynomial arithmetic used for erasure coding, coset evaluation, interpolation, and reconstruction. These are the low-level mathematical building blocks for the DAS scheme.",
      "invariants": [
        {
          "id": "INV-008",
          "text": "For polynomial multiplication: len(a) + len(b) <= FIELD_ELEMENTS_PER_EXT_BLOB, ensuring the product does not exceed the extended domain."
        },
        {
          "id": "INV-009",
          "text": "Lagrange interpolation produces the lowest-degree polynomial passing through all given points."
        }
      ],
      "functions": [
        {
          "id": "FN-010",
          "signature": "_fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement]) -> Sequence[BLSFieldElement]",
          "description": "Recursive Cooley-Tukey FFT over BLS field elements.",
          "classification": "internal"
        },
        {
          "id": "FN-011",
          "signature": "fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool=False) -> Sequence[BLSFieldElement]",
          "description": "FFT or inverse FFT over BLS field elements.",
          "classification": "internal"
        },
        {
          "id": "FN-012",
          "signature": "coset_fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool=False) -> Sequence[BLSFieldElement]",
          "description": "FFT/IFFT over a coset of the roots of unity. Avoids division-by-zero when dividing by vanishing polynomials.",
          "classification": "internal"
        },
        {
          "id": "FN-013",
          "signature": "polynomial_eval_to_coeff(polynomial: Polynomial) -> PolynomialCoeff",
          "description": "Interpolates a polynomial from evaluation form to coefficient form using inverse FFT.",
          "classification": "internal"
        },
        {
          "id": "FN-014",
          "signature": "add_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Sums two polynomials in coefficient form.",
          "classification": "internal"
        },
        {
          "id": "FN-015",
          "signature": "multiply_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Multiplies two polynomials in coefficient form.",
          "classification": "internal"
        },
        {
          "id": "FN-016",
          "signature": "divide_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Long polynomial division for two coefficient-form polynomials.",
          "classification": "internal"
        },
        {
          "id": "FN-017",
          "signature": "interpolate_polynomialcoeff(xs: Sequence[BLSFieldElement], ys: Sequence[BLSFieldElement]) -> PolynomialCoeff",
          "description": "Lagrange interpolation producing a polynomial in coefficient form.",
          "classification": "internal"
        },
        {
          "id": "FN-018",
          "signature": "vanishing_polynomialcoeff(xs: Sequence[BLSFieldElement]) -> PolynomialCoeff",
          "description": "Computes the vanishing polynomial on xs in coefficient form.",
          "classification": "internal"
        },
        {
          "id": "FN-019",
          "signature": "evaluate_polynomialcoeff(polynomial_coeff: PolynomialCoeff, z: BLSFieldElement) -> BLSFieldElement",
          "description": "Evaluates a coefficient-form polynomial at z using Horner's method.",
          "classification": "internal"
        },
        {
          "id": "FN-020",
          "signature": "coset_shift_for_cell(cell_index: CellIndex) -> BLSFieldElement",
          "description": "Returns the coset shift h that determines the evaluation domain for a given cell_index.",
          "classification": "internal"
        },
        {
          "id": "FN-021",
          "signature": "coset_for_cell(cell_index: CellIndex) -> Coset",
          "description": "Returns the full coset (evaluation domain) for a given cell_index.",
          "classification": "internal"
        }
      ],
      "data_structures": [],
      "state_variables": []
    },
    {
      "id": "SG-004",
      "name": "Data Reconstruction",
      "description": "Implements Reed-Solomon erasure code recovery. Given at least 50% of all columns (cells) for a blob, the original polynomial and all cells/proofs can be recovered using FFT-based techniques. This is the key availability guarantee of PeerDAS.",
      "invariants": [
        {
          "id": "INV-010",
          "text": "Reconstruction requires at least CELLS_PER_EXT_BLOB / 2 cells (50% of columns). This is the fundamental recovery threshold of the erasure code."
        },
        {
          "id": "INV-011",
          "text": "No duplicate cell indices are allowed in the input: len(cell_indices) == len(set(cell_indices))."
        },
        {
          "id": "INV-012",
          "text": "The recovered polynomial has degree at most FIELD_ELEMENTS_PER_BLOB - 1, matching the original blob polynomial."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-007",
          "text": "len(cell_indices) == len(cells)."
        },
        {
          "id": "PRE-008",
          "text": "CELLS_PER_EXT_BLOB / 2 <= len(cell_indices) <= CELLS_PER_EXT_BLOB."
        },
        {
          "id": "PRE-009",
          "text": "All cell_index values < CELLS_PER_EXT_BLOB."
        },
        {
          "id": "PRE-010",
          "text": "Each cell has length BYTES_PER_CELL."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-004",
          "text": "Returns the complete set of CELLS_PER_EXT_BLOB cells and CELLS_PER_EXT_BLOB KZG proofs for the blob."
        },
        {
          "id": "POST-005",
          "text": "The recovered polynomial_coeff has exactly FIELD_ELEMENTS_PER_BLOB coefficients (truncated from extended domain)."
        }
      ],
      "functions": [
        {
          "id": "FN-022",
          "signature": "recover_cells_and_kzg_proofs(cell_indices: Sequence[CellIndex], cells: Sequence[Cell]) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]",
          "description": "Given at least 50% of cells for a blob, recovers all cells and proofs using FFT-based Reed-Solomon recovery. Public method.",
          "classification": "public"
        },
        {
          "id": "FN-023",
          "signature": "recover_polynomialcoeff(cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals]) -> PolynomialCoeff",
          "description": "Recovers the original polynomial in coefficient form from partial cell evaluations using vanishing polynomial division over a coset FFT domain.",
          "classification": "internal"
        },
        {
          "id": "FN-024",
          "signature": "construct_vanishing_polynomial(missing_cell_indices: Sequence[CellIndex]) -> Sequence[BLSFieldElement]",
          "description": "Computes the polynomial that vanishes at every point corresponding to missing cells. Used in erasure code recovery.",
          "classification": "internal"
        },
        {
          "id": "FN-025",
          "signature": "recover_matrix(partial_matrix: Sequence[MatrixEntry], blob_count: uint64) -> Sequence[MatrixEntry]",
          "description": "Recovers the full matrix of cells and proofs for all blobs given a partial matrix with at least 50% columns per blob.",
          "classification": "internal"
        }
      ],
      "data_structures": [],
      "state_variables": []
    },
    {
      "id": "SG-005",
      "name": "Data Matrix and Column Sidecar Construction",
      "description": "Defines the data matrix structure (rows = blobs, columns = cell indices) and the construction of DataColumnSidecar objects for distribution. Each column sidecar packages the cells from a specific column index across all blobs in a block, along with KZG commitments, proofs, and a signed block header.",
      "invariants": [
        {
          "id": "INV-013",
          "text": "The matrix has exactly NUMBER_OF_COLUMNS (128) columns and up to MAX_BLOBS_PER_BLOCK_FULU (12) rows."
        },
        {
          "id": "INV-014",
          "text": "Each DataColumnSidecar contains cells from exactly one column index across all blobs in the block."
        },
        {
          "id": "INV-015",
          "text": "len(cells_and_kzg_proofs) == len(blob_kzg_commitments): each blob has corresponding cells and proofs."
        }
      ],
      "functions": [
        {
          "id": "FN-026",
          "signature": "compute_matrix(blobs: Sequence[Blob]) -> Sequence[MatrixEntry]",
          "description": "Returns the full flattened matrix of cells and proofs from a list of blobs.",
          "classification": "internal"
        },
        {
          "id": "FN-027",
          "signature": "get_data_column_sidecars(signed_block: SignedBeaconBlock, cells_and_kzg_proofs: Sequence[Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]]) -> Sequence[DataColumnSidecar]",
          "description": "Given a signed block and per-blob cells/proofs, assembles DataColumnSidecar objects for distribution to peers.",
          "classification": "internal"
        }
      ],
      "data_structures": [
        {
          "id": "DS-007",
          "name": "DataColumnSidecar",
          "definition": "Container { index: ColumnIndex, column: List[Cell, MAX_BLOB_COMMITMENTS_PER_BLOCK], kzg_commitments: List[KZGCommitment, MAX_BLOB_COMMITMENTS_PER_BLOCK], kzg_proofs: List[KZGProof, MAX_BLOB_COMMITMENTS_PER_BLOCK], signed_block_header: SignedBeaconBlockHeader, kzg_commitments_inclusion_proof: Vector[Bytes32, KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH] }",
          "description": "Container for a data column sidecar, packaging cells from one column across all blobs with associated KZG data and block header."
        },
        {
          "id": "DS-008",
          "name": "MatrixEntry",
          "definition": "Container { cell: Cell, kzg_proof: KZGProof, column_index: ColumnIndex, row_index: RowIndex }",
          "description": "Single entry in the data matrix, associating a cell with its proof and coordinates."
        },
        {
          "id": "DS-009",
          "name": "DataColumnIdentifier",
          "definition": "Container { block_root: Root, index: ColumnIndex }",
          "description": "Identifier for a specific data column sidecar by block root and column index."
        },
        {
          "id": "DS-010",
          "name": "RowIndex",
          "definition": "uint64",
          "description": "Row identifier in the matrix of cells."
        },
        {
          "id": "DS-011",
          "name": "ColumnIndex",
          "definition": "uint64",
          "description": "Column identifier in the matrix of cells."
        }
      ],
      "state_variables": [
        {
          "id": "SV-006",
          "name": "NUMBER_OF_COLUMNS",
          "value": "uint64(CELLS_PER_EXT_BLOB) (= 128)",
          "description": "Number of columns in the extended data matrix."
        },
        {
          "id": "SV-007",
          "name": "MAX_BLOBS_PER_BLOCK_FULU",
          "value": "uint64(12)",
          "description": "Maximum number of blobs in a single block (Fulu upgrade)."
        },
        {
          "id": "SV-008",
          "name": "KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH",
          "value": "uint64(4)",
          "description": "Merkle proof depth for blob_kzg_commitments inclusion in BeaconBlockBody."
        }
      ]
    },
    {
      "id": "SG-006",
      "name": "Custody Groups and Node Assignment",
      "description": "Defines the deterministic, public custody assignment mechanism. Columns are grouped into custody groups and nodes are assigned custody groups as a pseudorandom function of their node ID. Validators have higher custody requirements that scale with their balance.",
      "invariants": [
        {
          "id": "INV-016",
          "text": "custody_group_count <= NUMBER_OF_CUSTODY_GROUPS (128): a node cannot custody more groups than exist."
        },
        {
          "id": "INV-017",
          "text": "Custody selection is deterministic and public: any party can compute a node's custody groups from its node_id and custody_group_count."
        },
        {
          "id": "INV-018",
          "text": "Increasing custody_size extends the returned custody list (not a complete reshuffle), ensuring backward compatibility."
        },
        {
          "id": "INV-019",
          "text": "Returned custody groups contain no duplicates: len(custody_groups) == len(set(custody_groups))."
        },
        {
          "id": "INV-020",
          "text": "Nodes MUST custody all columns in each of their assigned custody groups."
        },
        {
          "id": "INV-021",
          "text": "Validator custody requirement is min(max(total_node_balance // BALANCE_PER_ADDITIONAL_CUSTODY_GROUP, VALIDATOR_CUSTODY_REQUIREMENT), NUMBER_OF_CUSTODY_GROUPS)."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-011",
          "text": "custody_group_count <= NUMBER_OF_CUSTODY_GROUPS."
        },
        {
          "id": "PRE-012",
          "text": "custody_group < NUMBER_OF_CUSTODY_GROUPS (for compute_columns_for_custody_group)."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-006",
          "text": "get_custody_groups returns exactly custody_group_count unique, sorted custody group indices."
        },
        {
          "id": "POST-007",
          "text": "compute_columns_for_custody_group returns columns_per_group (= NUMBER_OF_COLUMNS // NUMBER_OF_CUSTODY_GROUPS) sorted column indices."
        }
      ],
      "functions": [
        {
          "id": "FN-028",
          "signature": "get_custody_groups(node_id: NodeID, custody_group_count: uint64) -> Sequence[CustodyIndex]",
          "description": "Deterministically selects custody groups for a node based on its node_id using iterative hashing. Includes overflow protection.",
          "classification": "public"
        },
        {
          "id": "FN-029",
          "signature": "compute_columns_for_custody_group(custody_group: CustodyIndex) -> Sequence[ColumnIndex]",
          "description": "Maps a custody group index to its set of column indices using interleaved assignment.",
          "classification": "public"
        },
        {
          "id": "FN-030",
          "signature": "get_validators_custody_requirement(state: BeaconState, validator_indices: Sequence[ValidatorIndex]) -> uint64",
          "description": "Computes the minimum number of custody groups for a node with validators, scaling with total validator balance.",
          "classification": "public"
        }
      ],
      "data_structures": [
        {
          "id": "DS-012",
          "name": "CustodyIndex",
          "definition": "uint64",
          "description": "Custody group identifier in the set of custody groups."
        }
      ],
      "state_variables": [
        {
          "id": "SV-009",
          "name": "SAMPLES_PER_SLOT",
          "value": "8",
          "description": "Number of DataColumnSidecar random samples a node queries per slot."
        },
        {
          "id": "SV-010",
          "name": "NUMBER_OF_CUSTODY_GROUPS",
          "value": "128",
          "description": "Total number of custody groups available for nodes to custody."
        },
        {
          "id": "SV-011",
          "name": "CUSTODY_REQUIREMENT",
          "value": "4",
          "description": "Minimum number of custody groups an honest node custodies and serves samples from."
        },
        {
          "id": "SV-012",
          "name": "VALIDATOR_CUSTODY_REQUIREMENT",
          "value": "8",
          "description": "Minimum number of custody groups for honest nodes with validators attached."
        },
        {
          "id": "SV-013",
          "name": "BALANCE_PER_ADDITIONAL_CUSTODY_GROUP",
          "value": "Gwei(32 * 10**9)",
