{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7823.md",
  "eip": 7823,
  "title": "EIP-7823: Set Upper Bounds for MODEXP",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "execution",
  "requires": [198],
  "description": "Restricts each MODEXP precompile input field to a maximum of 8192 bits (1024 bytes) to reduce consensus bugs and simplify future EVMMAX replacement.",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "MODEXP Precompile Input Format",
      "description": "Defines the input format for the MODEXP precompile at address 0x0000000000000000000000000000000000000005, as inherited from EIP-198. The precompile accepts a serialized input composed of three length fields (each a 256-bit unsigned integer) followed by three variable-length value fields. The input is laid out sequentially as: <length_of_BASE> <length_of_EXPONENT> <length_of_MODULUS> <BASE> <EXPONENT> <MODULUS>.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "The MODEXP precompile resides at address 0x0000000000000000000000000000000000000005."
        },
        {
          "id": "INV-002",
          "text": "Input format is always: <length_of_BASE> <length_of_EXPONENT> <length_of_MODULUS> <BASE> <EXPONENT> <MODULUS>."
        },
        {
          "id": "INV-003",
          "text": "Each length field (length_of_BASE, length_of_EXPONENT, length_of_MODULUS) is a 256-bit (32-byte) unsigned integer specifying the byte-length of its corresponding value field."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "functions": [
        {
          "id": "FN-001",
          "signature": "MODEXP(length_of_BASE: uint256, length_of_EXPONENT: uint256, length_of_MODULUS: uint256, BASE: bytes, EXPONENT: bytes, MODULUS: bytes) -> bytes",
          "description": "Computes BASE^EXPONENT mod MODULUS. The three length fields are 256-bit unsigned integers specifying the byte-length of the respective value fields. Defined in EIP-198.",
          "classification": "public"
        }
      ],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "MODEXP Input Layout",
          "definition": "bytes32(length_of_BASE) ++ bytes32(length_of_EXPONENT) ++ bytes32(length_of_MODULUS) ++ bytes[length_of_BASE](BASE) ++ bytes[length_of_EXPONENT](EXPONENT) ++ bytes[length_of_MODULUS](MODULUS)",
          "description": "Sequential byte layout of the MODEXP precompile input as defined in EIP-198."
        }
      ],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "MODEXP_PRECOMPILE_ADDRESS",
          "value": "0x0000000000000000000000000000000000000005",
          "description": "The address of the MODEXP precompile on Ethereum."
        },
        {
          "id": "SV-002",
          "name": "length_of_BASE",
          "type": "uint256",
          "description": "Byte-length of the BASE input field."
        },
        {
          "id": "SV-003",
          "name": "length_of_EXPONENT",
          "type": "uint256",
          "description": "Byte-length of the EXPONENT input field."
        },
        {
          "id": "SV-004",
          "name": "length_of_MODULUS",
          "type": "uint256",
          "description": "Byte-length of the MODULUS input field."
        }
      ],
      "state_transitions": []
    },
    {
      "id": "SG-002",
      "name": "Upper Bound Enforcement on MODEXP Inputs",
      "description": "Introduces a hard upper bound on each of the three length inputs of the MODEXP precompile. Each of length_of_BASE, length_of_EXPONENT, and length_of_MODULUS MUST be less than or equal to 1024 bytes (8192 bits). This is the core normative change introduced by EIP-7823, reducing the infinite testing surface to a bounded one.",
      "invariants": [
        {
          "id": "INV-004",
          "text": "The maximum permitted value for length_of_BASE is 1024 bytes (8192 bits)."
        },
        {
          "id": "INV-005",
          "text": "The maximum permitted value for length_of_EXPONENT is 1024 bytes (8192 bits)."
        },
        {
          "id": "INV-006",
          "text": "The maximum permitted value for length_of_MODULUS is 1024 bytes (8192 bits)."
        },
        {
          "id": "INV-007",
          "text": "The upper bound constant is 1024 bytes, which equals 8192 bits. This value is the same for all three length fields."
        },
        {
          "id": "INV-008",
          "text": "The bound applies to each length field independently; there is no combined/aggregate limit."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-001",
          "text": "length_of_BASE <= 1024 (bytes)",
          "expression": "length_of_BASE <= MODEXP_INPUT_UPPER_BOUND"
        },
        {
          "id": "PRE-002",
          "text": "length_of_EXPONENT <= 1024 (bytes)",
          "expression": "length_of_EXPONENT <= MODEXP_INPUT_UPPER_BOUND"
        },
        {
          "id": "PRE-003",
          "text": "length_of_MODULUS <= 1024 (bytes)",
          "expression": "length_of_MODULUS <= MODEXP_INPUT_UPPER_BOUND"
        }
      ],
      "post_conditions": [
        {
          "id": "POST-001",
          "text": "If all preconditions are met, the precompile proceeds to normal execution (EIP-198 semantics) and returns BASE^EXPONENT mod MODULUS."
        }
      ],
      "functions": [
        {
          "id": "FN-002",
          "signature": "validate_modexp_bounds(length_of_BASE: uint256, length_of_EXPONENT: uint256, length_of_MODULUS: uint256) -> bool",
          "description": "Validates that all three MODEXP input length fields are within the 1024-byte upper bound. Returns true if all pass, false if any exceeds the limit. This is a logical function implicit in the specification.",
          "classification": "internal"
        }
      ],
      "data_structures": [],
      "state_variables": [
        {
          "id": "SV-005",
          "name": "MODEXP_INPUT_UPPER_BOUND",
          "value": 1024,
          "unit": "bytes",
          "equivalent_bits": 8192,
          "description": "The maximum allowed byte-length for each MODEXP input length field. Equal to 8192 bits."
        }
      ],
      "state_transitions": []
    },
    {
      "id": "SG-003",
      "name": "MODEXP Error Behavior on Bound Violation",
      "description": "Specifies the error behavior when any MODEXP input length field exceeds the 1024-byte upper bound. The precompile stops execution, returns an error, and consumes ALL provided gas. This is functionally equivalent to a precompile failure that burns all forwarded gas, analogous to how other precompile failures behave.",
      "invariants": [
        {
          "id": "INV-009",
          "text": "When a bound violation occurs, ALL gas provided to the precompile call is consumed (not just the gas that would have been used for computation)."
        },
        {
          "id": "INV-010",
          "text": "When a bound violation occurs, the precompile returns an error (execution failure), producing no output."
        },
        {
          "id": "INV-011",
          "text": "The violation of ANY single length field is sufficient to trigger the error path; all three need not exceed the limit."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-004",
          "text": "At least one of length_of_BASE, length_of_EXPONENT, or length_of_MODULUS exceeds 1024 bytes.",
          "expression": "length_of_BASE > 1024 || length_of_EXPONENT > 1024 || length_of_MODULUS > 1024"
        }
      ],
      "post_conditions": [
        {
          "id": "POST-002",
          "text": "The precompile execution stops immediately upon detecting the bound violation."
        },
        {
          "id": "POST-003",
          "text": "An error is returned to the caller (the precompile call is marked as failed)."
        },
        {
          "id": "POST-004",
          "text": "All gas provided to the precompile call is consumed (gas_remaining becomes 0)."
        },
        {
          "id": "POST-005",
          "text": "No output data is returned from the precompile."
        }
      ],
      "functions": [],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-001",
          "name": "Bound Violation Gas Consumption",
          "from": "MODEXP precompile called with oversized input length",
          "to": "Precompile returns error; all gas consumed",
          "trigger": "Any of length_of_BASE, length_of_EXPONENT, or length_of_MODULUS > 1024 bytes",
          "description": "When a MODEXP call has any input length field exceeding 1024 bytes, the precompile immediately halts, returns an error, and burns all gas passed to the call. No modular exponentiation computation is performed."
        }
      ]
    },
    {
      "id": "SG-004",
      "name": "MODEXP Successful Execution Path",
      "description": "Describes the normal (non-error) execution path of the MODEXP precompile after the upper-bound validation passes. When all three input length fields are within the 1024-byte limit, the precompile computes modular exponentiation as defined in EIP-198. Gas cost follows the EIP-198 pricing formula.",
      "invariants": [
        {
          "id": "INV-012",
          "text": "The computation semantics (BASE^EXPONENT mod MODULUS) are unchanged from EIP-198."
        },
        {
          "id": "INV-013",
          "text": "The gas pricing formula is unchanged from EIP-198."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-005",
          "text": "All three length fields pass the bound validation: length_of_BASE <= 1024 AND length_of_EXPONENT <= 1024 AND length_of_MODULUS <= 1024.",
          "expression": "length_of_BASE <= 1024 && length_of_EXPONENT <= 1024 && length_of_MODULUS <= 1024"
        }
      ],
      "post_conditions": [
        {
          "id": "POST-006",
          "text": "The precompile returns the result of BASE^EXPONENT mod MODULUS as a byte array of length equal to length_of_MODULUS."
        },
        {
          "id": "POST-007",
          "text": "Gas is consumed according to the EIP-198 pricing formula based on actual input lengths."
        }
      ],
      "functions": [
        {
          "id": "FN-003",
          "signature": "MODEXP_execute(BASE: bytes, EXPONENT: bytes, MODULUS: bytes) -> bytes",
          "description": "Executes BASE^EXPONENT mod MODULUS when all length preconditions are satisfied. Gas cost is computed per EIP-198 pricing formula. This represents the unchanged EIP-198 computation logic.",
          "classification": "public"
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-002",
          "name": "Valid MODEXP Computation",
          "from": "MODEXP precompile called with valid input lengths (all <= 1024 bytes)",
          "to": "Result returned; gas consumed per EIP-198 pricing",
          "trigger": "All length fields pass bound validation",
          "description": "Normal execution: the precompile validates the bounds, computes modular exponentiation per EIP-198 semantics, charges gas per the EIP-198 pricing formula, and returns the result."
        }
      ]
    },
    {
      "id": "SG-005",
      "name": "Input Validation Decision Logic",
      "description": "The complete decision tree for MODEXP precompile input validation introduced by EIP-7823. This subgraph connects the bound-check logic (SG-002) to either the error path (SG-003) or the success path (SG-004). The bound check is the first operation performed after the precompile is invoked, before any gas cost calculation or modular exponentiation.",
      "invariants": [
        {
          "id": "INV-014",
          "text": "The bound check is performed BEFORE any modular exponentiation computation occurs."
        },
        {
          "id": "INV-015",
          "text": "The bound check is performed BEFORE the EIP-198 gas cost calculation for the actual computation."
        },
        {
          "id": "INV-016",
          "text": "The three length fields are read from the first 96 bytes of input (3 x 32-byte uint256 values) before the bound check."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "functions": [],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-003",
          "name": "Bound Check Pass",
          "from": "Input validation (all length fields parsed)",
          "to": "Normal MODEXP execution (SG-004: EIP-198 semantics)",
          "trigger": "length_of_BASE <= 1024 AND length_of_EXPONENT <= 1024 AND length_of_MODULUS <= 1024",
          "description": "All three length fields are within the 1024-byte upper bound. Proceed to EIP-198 gas cost calculation and modular exponentiation."
        },
        {
          "id": "ST-004",
          "name": "Bound Check Fail",
          "from": "Input validation (all length fields parsed)",
          "to": "Error path with full gas consumption (SG-003)",
          "trigger": "length_of_BASE > 1024 OR length_of_EXPONENT > 1024 OR length_of_MODULUS > 1024",
          "description": "At least one length field exceeds 1024 bytes. Halt execution immediately, return error, consume all gas."
        }
      ]
    },
    {
      "id": "SG-006",
      "name": "Backwards Compatibility Analysis",
      "description": "Empirical analysis confirming that the 1024-byte upper bound does not break any historical on-chain usage of the MODEXP precompile on Ethereum mainnet. Data was collected from block 5,472,266 (April 20, 2018, shortly after Byzantium which introduced EIP-198) through block 21,550,926 (January 4, 2025). The maximum input length field ever observed in a successful call was 513 bytes, well within the new 1024-byte limit.",
      "invariants": [
        {
          "id": "INV-017",
          "text": "No historical MODEXP call on Ethereum mainnet (block 5,472,266 through block 21,550,926) used a successful input length field exceeding 513 bytes."
        },
        {
          "id": "INV-018",
          "text": "The overwhelming majority of historical MODEXP calls use 32-byte input lengths (over 99.7% of all calls)."
        },
        {
          "id": "INV-019",
          "text": "The new 1024-byte limit provides a ~2x safety margin over the maximum historically observed value of 513 bytes."
        },
        {
          "id": "INV-020",
          "text": "This is a backwards-incompatible consensus change, but no past transaction would have behaved differently under the new rules."
        }
      ],
      "pre_conditions": [],
