      "supported_use_cases": [
        {
          "id": "UC-001",
          "name": "RSA Signature Verification",
          "max_key_size_bits": 8192,
          "max_key_size_bytes": 1024,
          "common_key_sizes_bits": [1024, 2048, 4096],
          "common_key_sizes_bytes": [128, 256, 512],
          "description": "RSA signature verification with keys up to 8192 bits. The most commonly used key sizes (1024, 2048, 4096 bits) are well within the 1024-byte limit. Historical data confirms 512 bytes (4096 bits) as the maximum RSA key size used in practice on-chain."
        },
        {
          "id": "UC-002",
          "name": "Elliptic Curve Arithmetic",
          "max_field_size_bits": 384,
          "max_field_size_bytes": 48,
          "description": "Elliptic curve related computations using the MODEXP precompile for field arithmetic. Typically uses fields of 384 bits or fewer, far below the 8192-bit bound."
        }
      ]
    },
    {
      "id": "SG-008",
      "name": "Security Considerations and Consensus Bug Prevention",
      "description": "Security analysis of EIP-7823. The change is purely defensive: it reduces the accepted input range from unbounded to a finite, testable domain. No new security surface area is introduced. The motivation is rooted in the historical pattern of consensus bugs in MODEXP implementations caused by impractical input lengths that are now disallowed.",
      "invariants": [
        {
          "id": "INV-025",
          "text": "No new security surface area is introduced by this EIP."
        },
        {
          "id": "INV-026",
          "text": "The testing surface for MODEXP is no longer infinite; it is bounded by the 1024-byte limit on each input length field."
        },
        {
          "id": "INV-027",
          "text": "The MODEXP precompile has historically been a source of numerous consensus bugs, many caused by specifically crafted cases using impractical input lengths."
        },
        {
          "id": "INV-028",
          "text": "The change strictly reduces the accepted input domain; any input that was invalid before remains invalid."
        }
