          {"id": "SV-008", "name": "KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH", "value": "uint64(4)", "description": "Merkle proof depth for blob_kzg_commitments inclusion in BeaconBlockBody."}
        ]
      },
      {
        "id": "SG-006",
        "name": "Custody Groups and Node Assignment",
        "description": "Defines the deterministic, public custody assignment mechanism. Columns are grouped into custody groups and nodes are assigned custody groups as a pseudorandom function of their node ID.",
        "invariants": [
          {"id": "INV-016", "text": "custody_group_count <= NUMBER_OF_CUSTODY_GROUPS (128): a node cannot custody more groups than exist."},
          {"id": "INV-017", "text": "Custody selection is deterministic and public: any party can compute a node's custody groups from its node_id and custody_group_count."},
          {"id": "INV-018", "text": "Increasing custody_size extends the returned custody list (not a complete reshuffle), ensuring backward compatibility."},
          {"id": "INV-019", "text": "Returned custody groups contain no duplicates: len(custody_groups) == len(set(custody_groups))."},
          {"id": "INV-020", "text": "Nodes MUST custody all columns in each of their assigned custody groups."},
          {"id": "INV-021", "text": "Validator custody requirement is min(max(total_node_balance // BALANCE_PER_ADDITIONAL_CUSTODY_GROUP, VALIDATOR_CUSTODY_REQUIREMENT), NUMBER_OF_CUSTODY_GROUPS)."}
        ],
        "pre_conditions": [
          {"id": "PRE-011", "text": "custody_group_count <= NUMBER_OF_CUSTODY_GROUPS."},
          {"id": "PRE-012", "text": "custody_group < NUMBER_OF_CUSTODY_GROUPS (for compute_columns_for_custody_group)."}
        ],
        "post_conditions": [
          {"id": "POST-006", "text": "get_custody_groups returns exactly custody_group_count unique, sorted custody group indices."},
          {"id": "POST-007", "text": "compute_columns_for_custody_group returns columns_per_group sorted column indices."}
        ],
        "functions": [
          {"id": "FN-028", "signature": "get_custody_groups(node_id: NodeID, custody_group_count: uint64) -> Sequence[CustodyIndex]", "description": "Deterministically selects custody groups for a node based on its node_id using iterative hashing.", "classification": "public"},
          {"id": "FN-029", "signature": "compute_columns_for_custody_group(custody_group: CustodyIndex) -> Sequence[ColumnIndex]", "description": "Maps a custody group index to its set of column indices using interleaved assignment.", "classification": "public"},
          {"id": "FN-030", "signature": "get_validators_custody_requirement(state: BeaconState, validator_indices: Sequence[ValidatorIndex]) -> uint64", "description": "Computes the minimum number of custody groups for a node with validators, scaling with total validator balance.", "classification": "public"}
        ],
        "data_structures": [
          {"id": "DS-012", "name": "CustodyIndex", "definition": "uint64", "description": "Custody group identifier."}
        ],
        "state_variables": [
          {"id": "SV-009", "name": "SAMPLES_PER_SLOT", "value": "8", "description": "Number of DataColumnSidecar random samples a node queries per slot."},
          {"id": "SV-010", "name": "NUMBER_OF_CUSTODY_GROUPS", "value": "128", "description": "Total number of custody groups available."},
          {"id": "SV-011", "name": "CUSTODY_REQUIREMENT", "value": "4", "description": "Minimum number of custody groups an honest node custodies."},
          {"id": "SV-012", "name": "VALIDATOR_CUSTODY_REQUIREMENT", "value": "8", "description": "Minimum number of custody groups for honest nodes with validators."},
          {"id": "SV-013", "name": "BALANCE_PER_ADDITIONAL_CUSTODY_GROUP", "value": "Gwei(32 * 10**9)", "description": "Balance increment corresponding to one additional custody group."}
        ]
      },
      {
        "id": "SG-007",
        "name": "Custody Sampling Protocol",
        "description": "Defines the per-slot data availability sampling procedure. Each node downloads a minimum number of columns per slot, determined by max(SAMPLES_PER_SLOT, custody_group_count * columns_per_group).",
        "invariants": [
          {"id": "INV-022", "text": "sampling_size = max(SAMPLES_PER_SLOT, custody_group_count * columns_per_group): the sampling set always includes the custody set."},
          {"id": "INV-023", "text": "Sampling is successful if and only if the node retrieves ALL selected columns for the slot."},
          {"id": "INV-024", "text": "The sampling column set is a superset of the custody column set, ensuring consistency."}
        ],
        "pre_conditions": [
          {"id": "PRE-013", "text": "Node must have an established peer set providing coverage of the required column subnets."}
        ],
        "post_conditions": [
          {"id": "POST-008", "text": "If sampling succeeds, the node considers blob data available for the slot."},
          {"id": "POST-009", "text": "If 50%+ columns are obtained, reconstruction SHOULD be triggered."}
        ],
        "functions": [],
        "data_structures": [],
        "state_variables": []
      },
      {
        "id": "SG-008",
        "name": "Column Gossip and Subnet Distribution",
        "description": "Defines the gossipsub-based distribution of DataColumnSidecars over data_column_sidecar_{subnet_id} subnets.",
        "invariants": [
          {"id": "INV-025", "text": "DATA_COLUMN_SIDECAR_SUBNET_COUNT == 128."},
          {"id": "INV-026", "text": "subnet_id = column_index % DATA_COLUMN_SIDECAR_SUBNET_COUNT: deterministic column-to-subnet mapping."},
          {"id": "INV-027", "text": "Only the first valid sidecar for a given (slot, proposer_index, column_index) tuple is accepted."}
        ],
        "functions": [
          {"id": "FN-031", "signature": "compute_subnet_for_data_column_sidecar(column_index: ColumnIndex) -> SubnetID", "description": "Computes the gossipsub subnet ID for a given column index.", "classification": "public"}
        ],
        "data_structures": [],
        "state_variables": [
          {"id": "SV-014", "name": "DATA_COLUMN_SIDECAR_SUBNET_COUNT", "value": "128", "description": "Number of data column sidecar subnets."}
        ],
        "validation_rules": [
          {"id": "VR-001", "type": "REJECT", "text": "The sidecar must be valid as verified by verify_data_column_sidecar(sidecar)."},
