          {"id": "VR-003", "type": "IGNORE", "text": "The sidecar must not be from a future slot (with MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)."},
          {"id": "VR-004", "type": "IGNORE", "text": "The sidecar must be from a slot greater than the latest finalized slot."},
          {"id": "VR-005", "type": "REJECT", "text": "The proposer signature must be valid."},
          {"id": "VR-006", "type": "IGNORE", "text": "The sidecar's block's parent must have been seen."},
          {"id": "VR-007", "type": "REJECT", "text": "The sidecar's block's parent must pass validation."},
          {"id": "VR-008", "type": "REJECT", "text": "The sidecar must be from a higher slot than its parent block."},
          {"id": "VR-009", "type": "REJECT", "text": "The current finalized_checkpoint must be an ancestor of the sidecar's block."},
