          {"id": "VR-011", "type": "REJECT", "text": "The column data KZG proofs must be valid."},
          {"id": "VR-012", "type": "IGNORE", "text": "The sidecar must be the first for (slot, proposer_index, column_index) with valid signatures and proofs."},
          {"id": "VR-013", "type": "REJECT", "text": "The sidecar must be proposed by the expected proposer_index."}
        ]
