      {
        "id": "SG-010",
        "name": "Reconstruction and Cross-Seeding",
        "description": "Defines the protocol for reconstructing missing columns once a node has at least 50% of all columns, and the cross-seeding behavior to redistribute reconstructed data.",
        "invariants": [
          {"id": "INV-029", "text": "Reconstruction is possible if and only if >= 50% of all columns are available."},
          {"id": "INV-030", "text": "Once a column is obtained through reconstruction, the node MUST expose it as if received over the network."},
          {"id": "INV-031", "text": "If the node is subscribed to a reconstructed column's subnet, it MUST send the DataColumnSidecar to its mesh neighbors."},
          {"id": "INV-032", "text": "If the node is NOT subscribed to the subnet, it SHOULD still expose availability via gossip emission."}
        ],
        "pre_conditions": [
          {"id": "PRE-014", "text": "Node must have >= 50% of columns for the blob to trigger reconstruction."}
        ],
        "post_conditions": [
          {"id": "POST-010", "text": "After reconstruction, the node has a complete matrix view and can serve any column to peers."}
        ],
        "functions": [],
        "data_structures": [],
        "state_variables": []
      },
      {
        "id": "SG-011",
        "name": "Networking Transaction Wrapper Modification",
        "description": "Modifies the EIP-4844 blob transaction pool wrapper to include cell KZG proofs instead of blob-level KZG proofs.",
        "invariants": [
          {"id": "INV-033", "text": "wrapper_version == 1 for the current version."},
          {"id": "INV-034", "text": "cell_proofs contains exactly CELLS_PER_EXT_BLOB * len(blobs) proofs."},
          {"id": "INV-035", "text": "Blobs are sent without extension (half the cells); receiving nodes compute extension cells locally."},
          {"id": "INV-036", "text": "cell_proofs[i * CELLS_PER_EXT_BLOB + j] is the proof for cell j of compute_cells(blobs[i])."}
        ],
        "data_structures": [
          {"id": "DS-013", "name": "BlobTransactionWrapper", "definition": "rlp([tx_payload_body, wrapper_version, blobs, commitments, cell_proofs])", "description": "Modified EIP-4844 transaction pool wrapper including cell KZG proofs and a version byte."}
        ],
        "validation_rules": [
          {"id": "VR-014", "text": "Equal count of tx_payload_body.blob_versioned_hashes, blobs, and commitments."},
          {"id": "VR-015", "text": "cell_proofs contains exactly CELLS_PER_EXT_BLOB * len(blobs) proofs."},
          {"id": "VR-016", "text": "kzg_to_versioned_hash(commitments[i]) == tx_payload_body.blob_versioned_hashes[i] for all i."},
          {"id": "VR-017", "text": "KZG commitments match corresponding blobs and cell_proofs."}
        ]
