      {
        "id": "SG-015",
        "name": "Security Model - Withholding Attack Resistance",
        "description": "Formalizes the security argument against data withholding attacks.",
        "invariants": [
          {"id": "INV-048", "text": "The probability of tricking epsilon fraction of n nodes drops to negligible levels for epsilon >= 0.02 with n=10000."},
          {"id": "INV-049", "text": "Security relies on the pseudorandomness of custody group assignment and the independence of sampling queries across nodes."},
          {"id": "INV-050", "text": "Current parameters: with 10000 nodes, tricking 2% of the network has probability upper-bounded by 10^{-20.04}."}
        ],
        "security_parameters": [
          {"id": "SEC-001", "name": "n", "description": "Total number of sampling nodes.", "reference_value": "10000"},
          {"id": "SEC-002", "name": "m", "description": "Total number of samples possible (= NUMBER_OF_CUSTODY_GROUPS).", "reference_value": "128"},
          {"id": "SEC-003", "name": "k", "description": "Minimum number of samples a node must download (= SAMPLES_PER_SLOT).", "reference_value": "8"}
