        ],
        "state_transitions": [
          {"id": "ST-002", "name": "Valid MODEXP Computation", "from": "Valid input lengths (all <= 1024 bytes)", "to": "Result returned; gas consumed per EIP-198 pricing", "trigger": "All length fields pass bound validation"}
        ]
      },
