        "name": "Input Validation Decision Logic",
        "description": "The complete decision tree connecting the bound-check logic to either the error path (SG-003) or the success path (SG-004).",
        "invariants": [
          {"id": "INV-014", "text": "The bound check is performed BEFORE any modular exponentiation computation."},
          {"id": "INV-015", "text": "The bound check is performed BEFORE the EIP-198 gas cost calculation."},
          {"id": "INV-016", "text": "The three length fields are read from the first 96 bytes of input before the bound check."}
        ],
