        }
      },
      {
        "id": "SG-007",
        "name": "Supported Use Cases Under the Upper Bound",
        "description": "Documents cryptographic use cases that remain fully supported under the 1024-byte (8192-bit) upper bound.",
        "invariants": [
          {"id": "INV-021", "text": "RSA verification with key sizes up to 8192 bits remains fully supported."},
          {"id": "INV-022", "text": "Common RSA key sizes (1024, 2048, 4096 bits) are well within the limit."},
          {"id": "INV-023", "text": "Elliptic curve use cases (usually < 384 bits) remain fully supported."},
          {"id": "INV-024", "text": "The 8192-bit bound provides significant headroom over all known practical use cases."}
        ],
        "supported_use_cases": [
