      {
        "id": "SG-007",
        "name": "Custody Sampling Protocol",
        "description": "Defines the per-slot data availability sampling procedure. Each node downloads a minimum number of columns per slot, determined by max(SAMPLES_PER_SLOT, custody_group_count * columns_per_group).",
        "invariants": [
